/** Shape of the deployment of an environment (generated by scripts/generate-contracts.mjs from the manifest). */
export type Hex40 = `0x${string}`;

export type Underlying =
  | { readonly kind: "native"; readonly decimals: number }
  | { readonly kind: "erc20"; readonly address: Hex40; readonly symbol: string; readonly decimals: number };

export interface DeployedAsset {
  readonly ticker: string;
  readonly contract: string;
  readonly address: Hex40;
  readonly iToken: { readonly name: string; readonly symbol: string };
  readonly underlying: Underlying;
}

export interface Deployment {
  readonly env: "mainnet";
  readonly manifestSha256: string;
  readonly chainId: number;
  readonly owner: Hex40;
  readonly startBlock: bigint;
  readonly libraries: readonly { readonly name: string; readonly address: Hex40 }[];
  readonly assets: readonly DeployedAsset[];
}
